      "path": "01_content/package.json",
      "content": "{\n  \"name\": \"dsh-worktable\",\n  \"description\": \"工作台 Worktable：DeepSeek Harness 侧边栏的 agent 级项目容器（应用抽屉）\",\n  \"version\": \"0.5.1\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/Aisland-SJL/dsh-worktable.git\",\n    \"directory\": \"01_content\"\n  },\n  \"engines\": {\n    \"node\": \">=22\",\n    \"dsh\": \"0.2.0-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.5\"\n  },\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"cordis.patch.yml\",\n    \"dsh.plugin.json\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-primitives\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ]\n    },\n    \"compatibility\": {\n      \"dsh\": \"0.2.0-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.5\",\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-rc.3\": \"compatible\",\n        \"0.2.1-rc.5\": \"compatible\"\n      }\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node build.mjs\",\n    \"check\": \"node --check lib/index.js && node --check lib/client.js\",\n    \"pack\": \"node release-prep.mjs\",\n    \"test:gate\": \"node client-factory-gate.test.mjs\",\n    \"test:sidebar\": \"node ../04_test/sidebar-popup.test.mjs\",\n    \"test:input\": \"node ../04_test/host-input.test.mjs\",\n    \"test:session\": \"node ../04_test/session-compat.test.mjs\",\n    \"test:details\": \"node ../04_test/session-details.test.mjs\",\n    \"test:update\": \"node ../04_test/update-check.test.mjs\",\n    \"test:transport\": \"node ../04_test/host-transport.test.mjs\",\n    \"test:widget\": \"node ../04_test/widget-mount.test.mjs\",\n    \"test:security\": \"node --test ../04_test/request-auth.test.mjs ../04_test/preview-files.test.mjs ../04_test/sandboxed-frame.test.mjs\",\n    \"verify:remote\": \"node verify-remote.mjs\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"*\",\n    \"@deepseek-ai/dsh-client-locale\": \"*\",\n    \"@deepseek-ai/dsh-host-webserver\": \"*\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-host-webserver\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"esbuild\": \"^0.25.0\",\n    \"highlight.js\": \"^11.12.0\",\n    \"markdown-it\": \"^15.0.0\",\n    \"xterm\": \"^5.3.0\"\n  }\n}\n"
